<?php
declare(strict_types=1);
require_once '../config.php';
require_once '../session.php';
$lang=in_array($_COOKIE['aspi_lang']??'bn',['bn','en'],true)?$_COOKIE['aspi_lang']:'bn';$error='';$remainingTime=0;$tr=['bn'=>['title'=>'অ্যাডমিন লগইন','username'=>'ইউজারনেম','password'=>'পাসওয়ার্ড','login'=>'লগইন করুন','wait'=>'অতিরিক্ত চেষ্টা! দয়া করে %d সেকেন্ড অপেক্ষা করুন।','csrf'=>'CSRF টোকেন মেলেনি!','invalid'=>'ভুল ইউজারনেম বা পাসওয়ার্ড!'],'en'=>['title'=>'Admin Login','username'=>'Username','password'=>'Password','login'=>'Log in','wait'=>'Too many attempts. Please wait %d seconds.','csrf'=>'CSRF token mismatch.','invalid'=>'Invalid username or password.']];$t=$tr[$lang];$ip=$_SERVER['REMOTE_ADDR']??'0.0.0.0';
$s=$pdo->prepare("SELECT COUNT(*) FROM login_attempts WHERE ip_address=? AND attempt_time>DATE_SUB(NOW(),INTERVAL 15 MINUTE)");$s->execute([$ip]);$attempts=(int)$s->fetchColumn();if($attempts>=5){$s=$pdo->prepare("SELECT TIMESTAMPDIFF(SECOND,MAX(attempt_time),DATE_ADD(NOW(),INTERVAL 15 MINUTE)) FROM login_attempts WHERE ip_address=?");$s->execute([$ip]);$remainingTime=max(0,(int)$s->fetchColumn());if($remainingTime>0)$error=sprintf($t['wait'],$remainingTime);}
if($_SERVER['REQUEST_METHOD']==='POST'&&$remainingTime<=0){$u=trim((string)($_POST['username']??''));$p=(string)($_POST['password']??'');$csrf=(string)($_POST['csrf_token']??'');if(!Security::validateCSRF($csrf))$error=$t['csrf'];else{$configured=(string)($_ENV['ADMIN_USER']??'');$hash=(string)($_ENV['ADMIN_PASS_HASH']??'');$valid=$hash!==''?password_verify($p,$hash):hash_equals((string)($_ENV['ADMIN_PASS']??''),$p);if(hash_equals($configured,$u)&&$valid){session_regenerate_id(true);$_SESSION['admin_logged_in']=true;$_SESSION['admin_user']=$u;$_SESSION['last_activity']=time();$pdo->prepare("DELETE FROM login_attempts WHERE ip_address=?")->execute([$ip]);header('Location: index.php');exit;}$pdo->prepare("INSERT INTO login_attempts(ip_address) VALUES(?)")->execute([$ip]);$error=$t['invalid'];}}
