?><!DOCTYPE html><html lang="<?php echo htmlspecialchars($lang,ENT_QUOTES,'UTF-8'); ?>"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title><?php echo htmlspecialchars($t['title']); ?></title><link rel="icon" href="../assets/images/ASPI-Logo.png"><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Hind+Siliguri:wght@400;500;600;700;800&display=swap"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><style>:root{--b:#094f9d;--line:#dbe7f5;--text:#172033}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px;font-family:'Hind Siliguri',system-ui,sans-serif;background:linear-gradient(135deg,#f7faff,#eef5ff);color:var(--text)}.wrap{width:min(440px,100%);position:relative}.shell{background:#fff;border:1px solid var(--line);border-radius:28px;padding:30px;box-shadow:0 28px 80px rgba(9,79,157,.13)}.logo{width:82px;height:82px;display:block;margin:0 auto 16px;border-radius:22px;background:#fff;padding:7px;object-fit:contain;box-shadow:0 10px 28px rgba(9,79,157,.14)}h1{text-align:center;font-size:1.55rem;margin:0;font-weight:900}.sub{text-align:center;color:#64748b;font-size:.88rem;margin:6px 0 24px}.switch{position:absolute;right:16px;top:16px;border:1px solid var(--line);background:#eef5ff;color:var(--b);border-radius:999px;padding:7px 12px;font-weight:800;cursor:pointer}.field{margin-bottom:16px}.field label{display:block;font-size:.84rem;font-weight:800;margin-bottom:7px}.field input{width:100%;height:48px;border:1px solid #cbd9e8;border-radius:13px;padding:0 14px;background:#fff;color:var(--text);outline:none}.field input:focus{border-color:var(--b);box-shadow:0 0 0 3px rgba(9,79,157,.1)}.submit{width:100%;height:50px;border:0;border-radius:13px;background:linear-gradient(135deg,#094f9d,#1767bf);color:#fff;font-weight:900;font-size:1rem;cursor:pointer;box-shadow:0 12px 28px rgba(9,79,157,.2)}.submit:disabled{opacity:.55;cursor:not-allowed}.error{background:#fff1f2;border:1px solid #fecdd3;color:#be123c;padding:11px 13px;border-radius:12px;margin-bottom:18px;font-size:.86rem;font-weight:700}</style></head><body><div class="wrap"><div class="shell"><button type="button" class="switch" onclick="setLoginLang('<?php echo $lang==='bn'?'en':'bn'; ?>')"><?php echo $lang==='bn'?'EN':'বাংলা'; ?></button><img class="logo" src="../assets/images/ASPI-Logo.png" alt="ASPI"><h1><?php echo htmlspecialchars($t['title']); ?></h1><p class="sub">Ashab Siraj Polytechnic Institute</p><?php if($error): ?><div class="error"><?php echo htmlspecialchars($error); ?></div><?php endif; ?><form method="post" autocomplete="on"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrfToken,ENT_QUOTES,'UTF-8'); ?>"><div class="field"><label><?php echo htmlspecialchars($t['username']); ?></label><input name="username" type="text" autocomplete="username" required></div><div class="field"><label><?php echo htmlspecialchars($t['password']); ?></label><input name="password" type="password" autocomplete="current-password" required></div><button class="submit" type="submit" <?php echo $remainingTime>0?'disabled':''; ?>><i class="fa-solid fa-right-to-bracket"></i> <?php echo htmlspecialchars($t['login']); ?></button></form></div></div><script>function setLoginLang(l){document.cookie='aspi_lang='+l+';path=/;max-age=31536000;SameSite=Lax';location.reload()}</script></body></html>